const navItems=[...document.querySelectorAll('.nav-item')];const pages=[...document.querySelectorAll('.page')];const pageTitle=document.getElementById('pageTitle');const sectionLabel=document.getElementById('sectionLabel');const pageInfo={workspace:['WORKSPACE','Ask your knowledge'],documents:['KNOWLEDGE BASE','Documents'],research:['RESEARCH','Research'],system:['SYSTEM','System']};navItems.forEach(btn=>btn.addEventListener('click',()=>{navItems.forEach(x=>x.classList.remove('active'));btn.classList.add('active');pages.forEach(p=>p.classList.toggle('active',p.id===btn.dataset.page));const [label,title]=pageInfo[btn.dataset.page];sectionLabel.textContent=label;pageTitle.textContent=title}));document.getElementById('themeBtn').addEventListener('click',()=>document.body.classList.toggle('dark'));const messages=document.getElementById('messages');const input=document.getElementById('chatInput');function esc(v){return v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function addMessage(text,role='user'){const row=document.createElement('div');row.className='message';row.innerHTML=`<div class="avatar">${role==='user'?'Y':'N'}</div><div class="message-body"><div class="message-meta"><strong>${role==='user'?'You':'NovaOps'}</strong>${role==='assistant'?'<span>Gemini · demo</span>':''}</div><p>${role==='user'?esc(text):text}</p>${role==='assistant'?'<small>Sources: architecture.md · provider-routing.md</small>':''}</div>`;messages.appendChild(row)}function demoAnswer(q){const x=q.toLowerCase();if(x.includes('fallback')||x.includes('gemini'))return 'The provider router tries <strong>Gemini</strong> first, then <strong>Cloudflare Workers AI</strong>, then <strong>Ollama Cloud / Nemotron-3-Nano</strong>. If every generator fails, NovaOps should return the best retrieved evidence and citations instead of inventing an answer.';if(x.includes('ingestion')||x.includes('index'))return 'The ingestion flow is <strong>parse → chunk → embed → index</strong>. Content hashes allow unchanged files to be skipped during later synchronizations.';if(x.includes('unchanged')||x.includes('skip'))return 'Skipping unchanged files reduces duplicate work, embedding usage, vector writes, and synchronization time. Only new or changed content should be reprocessed.';return 'In production, NovaOps should retrieve relevant chunks first and generate only from that evidence. This prototype response is simulated and intentionally does not claim a live RAG backend.'}function send(){const q=input.value.trim();if(!q)return;addMessage(q,'user');input.value='';setTimeout(()=>addMessage(demoAnswer(q),'assistant'),250)}document.getElementById('sendBtn').addEventListener('click',send);input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}});document.querySelectorAll('.prompt-chip').forEach(b=>b.addEventListener('click',()=>{input.value=b.textContent;send()}));const fileInput=document.getElementById('fileInput');const browseBtn=document.getElementById('browseBtn');const dropZone=document.getElementById('dropZone');browseBtn.addEventListener('click',()=>fileInput.click());fileInput.addEventListener('change',()=>listFiles(fileInput.files));['dragenter','dragover'].forEach(ev=>dropZone.addEventListener(ev,e=>{e.preventDefault();dropZone.classList.add('drag')}));['dragleave','drop'].forEach(ev=>dropZone.addEventListener(ev,e=>{e.preventDefault();dropZone.classList.remove('drag')}));dropZone.addEventListener('drop',e=>listFiles(e.dataTransfer.files));function listFiles(files){const list=document.getElementById('docList');[...files].slice(0,5).forEach(file=>{const ext=(file.name.split('.').pop()||'FILE').toUpperCase().slice(0,4);const row=document.createElement('div');row.className='doc-row';row.innerHTML=`<div class="file-badge">${esc(ext)}</div><div><strong>${esc(file.name)}</strong><span>Local UI prototype · ${(file.size/1024/1024).toFixed(2)} MB</span></div><em>Selected</em>`;list.prepend(row)})}document.getElementById('researchBtn').addEventListener('click',()=>{const b=document.getElementById('researchBtn');const old=b.textContent;b.textContent='Research started ✓';b.disabled=true;setTimeout(()=>{b.textContent=old;b.disabled=false},1400)});